```java
package servlet;

import dao.UserDAO;
import model.User;

import javax.servlet.ServletException;
import javax.servlet.annotation.WebServlet;
import javax.servlet.http.HttpServlet;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;

@WebServlet("/register")
public class RegistrationServlet extends HttpServlet {

    private UserDAO userDAO;

    @Override
    public void init() {
        userDAO = new UserDAO();
    }

    /**
     * Display the registration form
     */
    @Override
    protected void doGet(HttpServletRequest request, HttpServletResponse response)
            throws ServletException, IOException {
        request.getRequestDispatcher("register.jsp").forward(request, response);
    }

    /**
     * Process the registration form submission
     */
    @Override
    protected void doPost(HttpServletRequest request, HttpServletResponse response)
            throws ServletException, IOException {

        // Retrieve form parameters
        String name = request.getParameter("name");
        String email = request.getParameter("email");
        String password = request.getParameter("password");
        String confirmPassword = request.getParameter("confirmPassword");

        // Validate inputs
        List<String> errors = validateInput(name, email, password, confirmPassword);

        // Check if email already exists
        if (errors.isEmpty() && userDAO.isEmailExists(email)) {
            errors.add("This email address is already registered.");
        }

        // If there are errors, return to form with error messages
        if (!errors.isEmpty()) {
            request.setAttribute("errors", errors);
            request.setAttribute("name", name);
            request.setAttribute("email", email);
            request.getRequestDispatcher("register.jsp").forward(request, response);
            return;
        }

        // Create user and register
        User user = new User(name.trim(), email.trim().toLowerCase(), password);
        boolean success = userDAO.registerUser(user);

        if (success) {
            request.setAttribute("userName", name);
            request.getRequestDispatcher("success.jsp").forward(request, response);
        } else {
            errors.add("Registration failed. Please try again later.");
            request.setAttribute("errors", errors);
            request.getRequestDispatcher("register.jsp").forward(request, response);
        }
    }

    /**
     * Validates user input and returns a list of error messages.
     */
    private List<String> validateInput(String name, String email, 
                                        String password, String confirmPassword) {
        List<String> errors = new ArrayList<>();

        // Name validation
        if (name == null || name.trim().isEmpty()) {
            errors.add("Name is required.");
        } else if (name.trim().length() < 2 || name.trim().length() > 100) {
            errors.add("Name must be between 2 and 100 characters.");
        }

        // Email validation
        if (email == null || email.trim().isEmpty()) {
            errors.add("Email is required.");
        } else if (!email.matches("^[A-Za-z0-9+_.-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$")) {
            errors.add("Please enter a valid email address.");
        }

        // Password validation
        if (password == null || password.isEmpty()) {
            errors.add("Password is required.");
        } else if (password.length() < 8) {
            errors.add("Password must be at least 8 characters long.");
        } else if (!password.matches(".*[A-Z].*")) {
            errors.add("Password must contain at least one uppercase letter.");
        } else if (!password.matches(".*[a-z].*")) {
            errors.add("Password must contain at least one lowercase letter.");
        } else if (!password.matches(".*\\d.*")) {
            errors.add("Password must contain at least one digit.");
        }

        // Confirm password
        if (password != null && !password.equals(confirmPassword)) {
            errors.add("Passwords do not match.");
        }

        return errors;
    }
}
```

